# McStas instrument file for TAS simulation

# Define constants
const m_n = 1.67493e-27;
const hbar = 1.05457e-34;
const meV_to_SI = 1.6022e-22;
const SI_to_meV = 6.2414e+21;
const MGUIDE = 3.2;
const W_para = 0.0025;
const R0_para = 0.99;
const Qc_para = 0.0217;
const alpha_para = 3.9;
const LGUIDE_1 = 18.65;
const LGUIDE_2 = 17.8;
const rho_AV = 1.23;
const L1 = 1.75;
const L2 = 2.2;

# Define instrument parameters
param kI = 1.55;
param kF = 1.55;
param wVS = 0.03;
param tilt = 0;
param SA = -1;
param A3 = 0;
param A4 = 70;
param L3 = 1.00;
param L4 = 1.00;
param Mono_flatswitch = 0;

# Calculate derived quantities
A1 = SM * RAD2DEG * asin(PI / (DM * kI));
A2 = 2 * A1;
RMH = (L1 + L2) / (2 * sin(A1 * DEG2RAD));
if (Mono_flatswitch == 1) RMH = 0.0;
RMV = (L1 + L2) * sin(A1 * DEG2RAD);
A5 = SA * RAD2DEG * asin(PI / (DA * kF));
A6 = 2 * A5;
RAH = (L3 + L4) / (2 * sin(A5 * DEG2RAD));
RAV = SA * 1 / rho_AV;

lambdaI = 2 * PI / kI;
EI = SI_to_meV * hbar * hbar * kI * kI * 1e20 / (2 * m_n);
SelFreq = 3956.06 / (lambdaI * (360 / (19.7 + (2.1 * tilt))) * 0.25);
dlambdaI = (1.75004E-05 * pow(lambdaI, 6) - 5.13903E-04 * pow(lambdaI, 5) + 6.04404E-03 * pow(lambdaI, 4) - 3.66989E-02 * pow(lambdaI, 3) + 1.22399E-01 * pow(lambdaI, 2) - 2.19626E-01 * lambdaI + 2.0E-01) * lambdaI;
l_min = lambdaI - dlambdaI;
l_max = lambdaI + dlambdaI;
e_min = 81.81 / l_max / l_max;
e_max = 81.81 / l_min / l_min;

beta_guide_1 = LGUIDE_1 / 2800 * 180 / PI;
beta_guide_2 = LGUIDE_2 / 2800 * 180 / PI;
s_guide_1 = 2800 - sqrt(2800 * 2800 - LGUIDE_1 * LGUIDE_1);
s_guide_2 = 2800 - sqrt(2800 * 2800 - LGUIDE_2 * LGUIDE_2);

# Define components
component Progress_bar {
    type = "Progress_bar"
    parameters = {
        xwidth = 0.2
        yheight = 0.2
    }
}

component Source_gen {
    type = "Source_gen"
    parameters = {
        radius = 0.0775
        dist = 1.53
        focus_xw = 0.2
        focus_yh = 0.125
        I1 = 1e10
        T1 = 45
        Lmin = l_min
        Lmax = l_max
    }
}

component Guide {
    type = "Guide"
    parameters = {
        w1 = 0.170696
        h1 = 0.129
        w2 = 0.340522
        h2 = 0.129
        l = 1.870
        R0 = R0_para
        Qc = Qc_para
        alpha = alpha_para
        m = MGUIDE
        W = W_para
    }
}

component Guide_curved {
    type = "Guide_curved"
    parameters = {
        w1 = 0.06
        h1 = 0.125
        l = LGUIDE_1
        R0 = R0_para
        Qc = Qc_para
        alpha = alpha_para
        m = MGUIDE
        W = W_para
        curvature = 3920
    }
}

component Guide_tapering {
    type = "Guide_tapering"
    parameters = {
        option = "elliptical"
        w1 = 0.06
        h1 = 0.125
        l = 2.5
        linw = 2.9
        loutw = 0.4
        R0 = 0.99
        Qcx = Qc_para
        Qcy = Qc_para
        alphax = alpha_para
        alphay = alpha_para
        W = 0.002
        mx = 5.2
        my = MGUIDE
        segno = 800
    }
}

component Guide_channeled {
    type = "Guide_channeled"
    parameters = {
        w1 = 0.03
        h1 = 0.125
        w2 = 0.15
        h2 = 0.125
        l = 1.475
        R0 = R0_para
        nslit = 1
        Qcx = Qc_para
        Qcy = Qc_para
        alphax = alpha_para
        alphay = alpha_para
        W = W_para
        mx = 0
        my = MGUIDE
    }
}

component Monochromator_curved {
    type = "Monochromator_curved"
    parameters = {
        zwidth = 0.02
        yheight = 0.02
        gap = 0.0005
        NH = 15
        NV = 7
        mosaich = 40
        mosaicv = 40
        r0 = 1.0
        t0 = 0.00001
        RV = RMV
        RH = RMH
    }
}

component PSD_monitor {
    type = "PSD_monitor"
    parameters = {
        nx = 50
        ny = 50
        xwidth = 0.20
        yheight = 0.20
        restore_neutron = 1
    }
}

component E_monitor {
    type = "E_monitor"
    parameters = {
        nE = 200
        xwidth = 0.17
        yheight = 0.135
        Emin = e_min
        Emax = e_max
        restore_neutron = 1
    }
}

component Divergence_monitor {
    type = "Divergence_monitor"
    parameters = {
        nh = 20
        nv = 20
        maxdiv_h = 4
        maxdiv_v = 4
        restore_neutron = 1
    }
}

component PSDlin_monitor {
    type = "PSDlin_monitor"
    parameters = {
        nbins = 30
        xmin = -0.1
        xmax = 0.1
        ymin = -0.1
        ymax = 0.1
        restore_neutron = 1
    }
}

# Build the instrument
instrument TAS_instrument {
    # Source
    Progress_bar AT [0, 0, 0] RELATIVE ABSOLUTE ROTATED [0, 0, 0] RELATIVE ABSOLUTE
    Source_gen AT [0, 0, 0] RELATIVE Progress_bar ROTATED [0, 0, 0] RELATIVE Progress_bar

    # Arms and guides
    Arm AT [0, 0, 1.530] RELATIVE Progress_bar ROTATED [0, 0, 0] RELATIVE Progress_bar
    Guide AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Arm AT [-0.1277, 0, 3.405] RELATIVE Progress_bar ROTATED [0, -2.15, 0] RELATIVE Progress_bar
    Guide AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Arm AT [0, 0, 1.549] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm
    Guide_curved AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 180] RELATIVE Arm

    Arm AT [-s_guide_1, 0, LGUIDE_1] RELATIVE Arm ROTATED [0, -beta_guide_1, 0] RELATIVE Arm
    PSD_monitor AT [0, 0, 0.19] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Selector AT [0, 0, 0.2] RELATIVE Arm ROTATED [0, tilt, 90] RELATIVE Arm

    PSD_monitor AT [0, 0, 0.46] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Arm AT [0, 0, 0.47] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm
    Guide_curved AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 180] RELATIVE Arm

    Arm AT [-s_guide_2, 0, LGUIDE_2] RELATIVE Arm ROTATED [0, -beta_guide_2, 0] RELATIVE Arm
    Guide AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Arm AT [0.0000, 0, 3.500] RELATIVE Arm ROTATED [0, 0.000, 0.00] RELATIVE Arm
    Guide_tapering AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Slit AT [0, 0, 2.900] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Arm AT [0.0000, 0, 2.925] RELATIVE Arm ROTATED [0, 0.000, 0.00] RELATIVE Arm
    Guide_channeled AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Arm AT [0, 0, 1.475] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    E_monitor AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Arm AT [0, 0, 0.25] RELATIVE Arm ROTATED [0, A1, 0] RELATIVE Arm
    Monochromator_curved AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    Arm AT [0, 0, 0] RELATIVE Arm ROTATED [0, A2, 0] RELATIVE Arm

    E_monitor AT [0, 0, 0.15] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Arm AT [0, 0, L2 - 0.1] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm
    E_monitor AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Arm AT [0, 0, L2] RELATIVE Arm ROTATED [0, A3, 0] RELATIVE Arm
    Arm AT [0, 0, 0] RELATIVE Arm ROTATED [0, A4, 0] RELATIVE Arm

    Divergence_monitor AT [0, 0, L2 - 0.05] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    Divergence_monitor AT [0, 0, L2 - 0.04] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE ABSOLUTE

    PSD_monitor AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm

    PSDlin_monitor AT [0, 0, 0] RELATIVE Arm ROTATED [0, 0, 0] RELATIVE Arm
}

# Run the simulation
run {
    seed = 123456789
    ncount = 1e6
    wait_s = 0
    output = "tas_results.txt"
    print = 1
    print_all = 1
    print_monitor = 1
    print_monitor_all = 1
    print_monitor_error = 1
    print_monitor_events = 1
    print_monitor_ncount = 1
    print_monitor_rel_err = 1
    print_monitor_abs_err = 1
    print_monitor_total = 1
    print_monitor_total_error = 1
    print_monitor_total_events = 1
    print_monitor_total_ncount = 1
    print_monitor_total_rel_err = 1
    print_monitor_total_abs_err = 1
}
